const n="tb_canteen_feedback";class a{getStored(){const e=localStorage.getItem(n);if(!e)return[];try{return JSON.parse(e)}catch{return[]}}save(e){localStorage.setItem(n,JSON.stringify(e)),window.dispatchEvent(new CustomEvent("tb_feedback_updated"))}async submitFeedback(e){const r=this.getStored(),t={...e,id:"fb-"+Date.now(),createdAt:new Date().toISOString()};return r.unshift(t),this.save(r),t}async getFeedbackForOrder(e){return this.getStored().find(t=>t.orderId===e)||null}async getAllFeedback(){return this.getStored()}}const c=new a;export{c as f};
